llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C26"],
      "claim": "Codeine, a 4,5-epoxymorphinan opioid with an N-methyl group, has an absolute oral bioavailability of 80.5% in healthy subjects, demonstrating that the morphinan scaffold can achieve high oral bioavailability despite first-pass metabolism.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C16"],
      "claim": "Ethinylestradiol, a phenolic rigid polycyclic steroid subject to extensive presystemic and hepatic first-pass metabolism, has an absolute oral bioavailability of 62 ± 10% in subjects, supporting high F for a phenolic polycyclic compound.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C33"],
      "claim": "Norethisterone, a rigid steroid with a ketone and substantial first-pass metabolism, has an absolute oral bioavailability of 64 ± 8% in subjects, supporting high F for a rigid lipophilic ketone-containing molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Pentazocine, a phenolic opioid analgesic with a rigid benzomorphan scaffold, has a mean absolute oral bioavailability of 18% in healthy subjects, just below the 20% threshold, providing affirmative evidence for low F in a structurally related opioid.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C52"],
      "claim": "Meptazinol, a phenolic tertiary amine with extensive hepatic first-pass metabolism, has an absolute oral bioavailability of 8.7 ± 1.6% in healthy volunteers, showing that phenolic basic amines can be low-bioavailability drugs.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is hydromorphone, a 4,5-epoxymorphinan opioid with a phenolic OH, N-methyl, and 6-ketone. The closest morphinan analogue (codeine) has high oral bioavailability (80.5%), and other phenolic/rigid polycyclic drugs with first-pass metabolism (ethinylestradiol, norethisterone) exceed 20%. Although phenolic opioid/amine analogues such as pentazocine and meptazinol show low F, their structural differences (benzomorphan/azepane, different N-substituents) reduce transferability; the morphinan scaffold and known behavior of hydromorphone support F ≥20%. Prediction: high.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement for hydromorphone is provided; prediction relies on transfer from analogues.",
    "The closest high-F analogue (codeine) differs at the 3-position (methoxy vs phenolic OH) and 6-position (hydroxyl vs ketone), which may alter first-pass glucuronidation.",
    "The closest low-F analogue (pentazocine) differs in the core scaffold and N-substituent, limiting direct transfer."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

